        S = input[index + 1]
        index += 2
        zeros_even = zeros_odd = ones_even = ones_odd = 0
        for i in range(N):
            if S[i] == '0':
                if i % 2 == 0:
                    zeros_even += 1
                else:
                    zeros_odd += 1
            else:
                if i % 2 == 0:
                    ones_even += 1
                else:
                    ones_odd += 1
        max_01 = min(zeros_even, ones_odd) + min(zeros_odd, ones_even)
        results.append(max_01)
    for result in results:
